#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long calculate(long long n, int x, long long even, long long odd, unordered_map<long long, long long>& c0, unordered_map<long long, long long>& c1) {
    if (x == 0) {
        if (c0.count(n)) return c0[n];
        if (n == 1) return even % MOD;
        if (n == 2) return ((even % MOD) * (even % MOD) + (odd % MOD) * (odd % MOD)) % MOD;
        long long a = calculate(n / 2, 0, even, odd, c0, c1);
        long long b = calculate(n - n / 2, 0, even, odd, c0, c1);
        long long c = calculate(n / 2, 1, even, odd, c0, c1);
        long long d = calculate(n - n / 2, 1, even, odd, c0, c1);
        long long res = (a * b + c * d) % MOD;
        c0[n] = res;
        return res;
    } else {
        if (c1.count(n)) return c1[n];
        if (n == 1) return odd % MOD;
        if (n == 2) return ((even % MOD) * (odd % MOD) + (odd % MOD) * (even % MOD)) % MOD;
        long long a = calculate(n / 2, 0, even, odd, c0, c1);
        long long b = calculate(n - n / 2, 1, even, odd, c0, c1);
        long long c = calculate(n / 2, 1, even, odd, c0, c1);
        long long d = calculate(n - n / 2, 0, even, odd, c0, c1);
        long long res = (a * b + c * d) % MOD;
        c1[n] = res;
        return res;
    }
}

long long powerMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, start, end;
    cin >> n >> m >> start >> end;

    long long totalCells = n * m;

    if (totalCells % 2 == 0) {
        long long length = end - start + 1;
        long long evenCount = length / 2;
        if (length % 2 == 0 && start % 2 == 0) {
            evenCount++;
        }
        long long oddCount = length - evenCount;

        unordered_map<long long, long long> cacheZeroMap, cacheOneMap;
        cout << calculate(totalCells, 0, evenCount, oddCount, cacheZeroMap, cacheOneMap) << "\n";
    } else {
        long long answer = powerMod(end - start + 1, totalCells);
        cout << answer << "\n";
    }
    return 0;
}

